"""Construction and operation pages, verified against the installed 1.7.10 code.
Coordinates in Blood Magic pages are relative to the altar block, not its pedestal.
"""
byid={n['id']:n for n in quests}
def page(key,title,text,image=None):
 elements=[dict(type='text',text=text)]
 if image:elements.insert(0,dict(type='image',resource='sigmaquests:textures/guides/'+image+'.png',width=320,height=200))
 byid[key].setdefault('richPages',[]).append(dict(title=title,elements=elements))

page('bm_altar','Первый алтарь: LP и сеть души','''1. Поставьте кровавый алтарь и оставьте вокруг место 23×23 для позднего расширения. Сам блок — уровень I; руны пока не требуются.
2. Положите камень в алтарь правой кнопкой. Для чистой плитки нужен запас LP; посмотрите стоимость в рецепте текущей сборки. Кинжал самопожертвования добавляет кровь в ближайший алтарь ценой здоровья. Оставляйте запас здоровья и еду.
3. Проверяйте заполнение Сферой прорицания. Когда крови хватает, камень превращается в плитку. Если процесс не заканчивается, проверьте уровень алтаря и непрерывную подачу LP.
4. Сфера крови связывается с игроком правой кнопкой. LP внутри алтаря и личная сеть души — разные запасы. Чтобы наполнить сеть, положите связанную сферу в наполненный алтарь; для обработки плитки вместо неё нужен сам ингредиент.
5. Сначала сделайте несколько плиток вручную. Автоматический импорт включайте после проверки: иначе он заберёт промежуточную плитку раньше нужной стадии.''')
page('bm_runes','Уровень II — 8 рун','''Считайте координаты блока алтаря за (0,0,0). Y направлен вверх.
На Y=-1 уложите кольцо 3×3: восемь рун вокруг свободного центрального места. В центре над ним, на Y=0, стоит сам алтарь. Руны не должны находиться на одной высоте с алтарём.
Вид сверху нижнего слоя: РРР / Р.Р / РРР. «Р» — кровавая руна или совместимая руна улучшения. Точка — центр под алтарём.
После установки проверьте уровень Сферой прорицания. Если остался I, проверьте все восемь позиций и высоту. Этот уровень нужен для усиленных плиток; наличие рун в инвентаре не подтверждает сборку.''','blood_altar_t2')
page('bm_imbued','Уровень III — ещё 20 рун','''Сохраните восемь рун уровня II. Добавьте на Y=-2 четыре стороны: X=±3 при Z от -2 до 2 и Z=±3 при X от -2 до 2. Получается 20 новых рун, суммарно 28.
По углам X=±3,Z=±3 поставьте по два любых непустых блока на Y=-1 и Y=0, затем светокамень на Y=+1. Всего четыре угловые стойки со светокамнем. На углах нижнего рунного контура рун нет.
Проверьте III уровень Сферой прорицания, затем заполните алтарь и обработайте усиленную плитку в пропитанную. Сначала обеспечьте LP, потом добавляйте ускорение: быстрый алтарь без крови просто остановится.''','blood_altar_t3')
page('bm_demonic','Уровень IV — 56 рун всего','''Сохраните всю конструкцию III уровня. На Y=-3 добавьте стороны X=±5,Z=-3…3 и Z=±5,X=-3…3: ещё 28 рун.
Углы X=±5,Z=±5: четыре непустых блока в каждой стойке на Y=-2,-1,0,+1; сверху на Y=+2 — блок большого кровавого каменного кирпича. Всего четыре навершия.
Новые углы не прилегают вплотную к концам рунной стороны: не заполняйте пробелы рунами «для симметрии» вместо нужных координат. Проверьте IV уровень, запас LP и рецепт демонической плитки.''','blood_altar_t4')
page('bm_demons','Уровень V — 108 рун всего','''Сохраните IV уровень. На Y=-4 добавьте четыре стороны X=±8,Z=-6…6 и Z=±8,X=-6…6: ещё 52 руны, суммарно 108.
На четырёх углах X=±8,Z=±8,Y=-3 поставьте маяки. Проверка уровня в Blood Magic 1.3.3 требует блок маяка; активный луч и полная минеральная пирамида не входят в эту проверку.
Проверьте V уровень Сферой прорицания. Демонический мир и добыча реагентов — отдельная механика: не запускайте Convocation только ради проверки уровня алтаря возле базы.''','blood_altar_t5')
page('bm_transcendent','Уровень VI — 184 руны всего','''Сохраните V уровень. На Y=-5 добавьте стороны X=±11,Z=-9…9 и Z=±11,X=-9…9: ещё 76 рун, всего 184.
Углы X=±11,Z=±11: непустые блоки на Y=-4…+2, сверху на Y=+3 — кристальный кластер Blood Magic. Суммарный габарит 23×23, от нижних рун до вершины — девять слоёв.
Все высоты отсчитываются от блока алтаря. Сфера должна показать VI. Кластеры требуют позднего развития; обычный кристалл другого мода не заменяет нужный блок.''','blood_altar_t6')
page('bm_ritual','Первый ритуал: Serenade of the Nether','''Для первого примера удобнее Serenade of the Nether: он создаёт лаву над главным ритуальным камнем. Делайте его на негорючей площадке с ограждением.
Подготовьте главный ритуальный камень, ритуальные камни требуемых стихий, связанный с собой слабый активационный кристалл и LP в личной сети души. Требования конкретного ритуала смотрите в его выбранной схеме; LP в алтаре не оплачивают работу сами по себе.
Выберите ритуал Предсказателем ритуалов. Применяйте его к главному камню с нужными камнями в инвентаре, пока все позиции не будут заполнены и окрашены. Проверьте, что выбран именно нужный ритуал, а не только совпало число камней.
Примените связанный слабый активационный кристалл к главному камню. При отказе проверьте целостность схемы, владельца и LP сети. Редстоуновый сигнал на главном камне приостанавливает работающий ритуал. Не удаляйте камни во время работы.''')
page('bm_diviner','Точный пример: Serenade of Water','''Главный ритуальный камень — (0,0,0). Четыре водных ритуальных камня находятся на той же высоте в точках (-1,0,-1),(-1,0,+1),(+1,0,-1),(+1,0,+1). Камни занимают углы квадрата 3×3; стороны оставьте свободными.
После проверки схемы свяжите активационный кристалл с собой и активируйте главный камень. Вода появляется непосредственно над ним, в (0,+1,0); это место оставьте пустым и подготовьте отвод воды.
Ритуал расходует LP личной сети. Отсутствие воды при полной ёмкости алтаря ещё не означает поломку: проверьте сеть владельца и редстоуновую остановку. Изображение показывает только постройку до запуска.''','blood_ritual_water')
page('ic2_reactor','Минимальный учебный EU-реактор','''Схема ниже предназначена для обычного электрического реактора IC2 Experimental 2.2.827, без жидкостной оболочки. Дополнительные реакторные камеры не нужны: исходное поле содержит 3 столбца и 6 строк.
Положите ОДИН одиночный урановый топливный стержень в верхний левый слот, а обычный теплоотвод — сразу справа. Все остальные слоты оставьте пустыми. Не используйте сдвоенный/счетверённый стержень и не добавляйте отражатели.
Одиночный стержень без соседних топливных стержней и отражателей создаёт 4 единицы тепла за реакторный цикл. Обычный теплоотвод принимает тепло от соседнего стержня и рассеивает до 6 за цикл. Это разные единицы относительно EU/t; не путайте реакторный цикл с каждым игровым тиком.
Сначала поставьте рычаг в положение «выключено», соберите охлаждение и подключите подходящий кабель/накопитель. Включите, наблюдайте нагрев корпуса и состояние теплоотвода. Корпус не должен накапливать тепло. Для остановки снимите редстоуновый сигнал. Перед перестановкой охлаждения остановите реактор и выньте топливо.
Эта схема — учебная маломощная установка. Её охлаждение нельзя переносить на другое топливо или расширять копированием вплотную без нового расчёта.''','ic2_reactor_grid')
page('ic2_chambers','Что меняет реакторная камера','''Каждая камера, непосредственно примыкающая к реактору, добавляет один столбец слотов. Базовый реактор — 3×6; шесть камер дают 9×6. Сами камеры не охлаждают топливо автоматически.
Число импульсов зависит от соседних топливных стержней и отражателей по четырём сторонам. Диагональное соседство импульс не даёт. Сначала сохраните схему, затем считайте тепло и охлаждение для каждого компонента.
Добавление столбцов не требует немедленно заполнять их топливом. Оставьте учебную пару из предыдущего задания до проверки новой схемы.''')
page('ic2_fluidreactor','Жидкостный контур — отдельный проект','''Электрический реактор из предыдущего задания не становится жидкостным от одной трубы. Нужны шесть камер и оболочка реакторного сосуда 5×5×5 с правильно установленными люком, редстоуновым и жидкостными портами.
Внутри применяйте охлаждающую жидкость IC2; горячий теплоноситель направляйте в жидкостный теплообменник. Возвращайте охлаждённый теплоноситель отдельной линией. Теплообменник передаёт HU через свою рабочую грань, а не через обычный EU-кабель.
До топлива проверьте герметичность структуры, распознавание режима, наличие теплоносителя, оба направления жидкости и постоянное потребление тепла. Пустой бак или остановившийся возврат — повод выключить подачу сигнала, а не добавлять топливо.''')
page('tc_infusion','Матрица наполнения: сборка','''Поставьте центральный магический пьедестал. Руническая матрица находится на два блока выше него: между верхом пьедестала и матрицей остаётся свободный блок.
Четыре угла вокруг центра: по одному магическому каменному кирпичу в нижнем слое и по одному магическому каменному блоку над ним. Матрица располагается над серединой этих четырёх стоек. Примените заряженный жезл к матрице, чтобы сформировать конструкцию; необходимо изучение INFUSION.
Внешние пьедесталы разместите симметрично вокруг центрального. На снимке показаны четыре — для примера; количество зависит от выбранного рецепта. Банки с нужной эссенцией держите в зоне доступа установки.
Для операции положите основу в центр, ингредиенты разложите по внешним пьедесталам, приготовьте требуемые аспекты и активируйте матрицу жезлом. Не путайте начало операции с формированием самой постройки.''','thaum_infusion')
page('tc_stability','Стабилизация и первая операция','''Симметрию считайте относительно центра матрицы: предмету стабилизации на одной стороне соответствует такой же на противоположной. Используйте свечи, черепа и поддерживаемые стабилизаторы; случайная куча предметов только с одной стороны не заменяет симметрию.
До запуска сверьте каждый аспект и его количество, центральную основу и все компоненты по исследованному рецепту. Поставьте резервные ингредиенты рядом, но вне области, где матрица может их подобрать.
Если ингредиент исчез с пьедестала из-за нестабильности, восполните именно его. Не разбирайте центр посреди процесса. Стабилизаторы уменьшают риск, но не создают недостающую эссенцию и не отменяют нестабильность рецепта.''')
page('wit_altar','Алтарь Witchery: 3×2','''Поставьте шесть алтарных блоков прямоугольником 3×2 на одной высоте. Это один алтарь, а не две отдельные колонны по три. Снимок показывает основание до размещения улучшений.
Посадите поблизости разнообразные деревья, цветы и культуры на подходящей почве. Откройте алтарь и сравните максимальную силу и восстановление. Дальнейшее повторение одинакового растения имеет ограниченную пользу.
Установите поддерживаемые улучшения на верх алтаря: голову/череп, канделябр и кубок. Заряженный камень и артана выполняют свои роли; сравнивайте показатели после каждого изменения.
Потребляющие силу устройства ставьте в радиусе алтаря. Перед ритуалом дождитесь запаса, достаточного для его цены, и проверьте восстановление при работающих соседних устройствах.''','witchery_altar')
page('wit_chalk','Круги: порядок выполнения ритуала','''Подготовьте ровную площадку с цельным верхом блоков. Откройте «Магию кругов», выберите конкретный обряд и сверяйте рисунок, цвет мела, ингредиенты, время суток и цену силы. У разных обрядов разные круги: единая схема для всех неверна.
Сначала нарисуйте золотым мелом центральный символ, затем требуемые белые, адские и/или потусторонние круги по рисунку рецепта. Оставляйте площадку без травы, снега и посторонних предметов.
Бросьте точные ингредиенты на центр, убедитесь в доступности силы алтаря, затем активируйте центральный символ правой кнопкой. Если обряд требует сущность, участника, ночь или ковен, эти условия проверяются отдельно от наличия предметов.
При отказе не добавляйте ингредиенты вслепую: пересчитайте предметы на земле, проверьте повреждённые линии, центр, условия обряда и запас силы. Талисман круга сохраняет рисунок, но не оплачивает обряд и не заменяет реагенты.''')
page('ae_patterns','Что приготовить до первого заказа','''Шаблоны можно кодировать до запуска первого автокрафта. Подготовьте терминал шаблонов и пустые шаблоны; в режиме верстака положите рецепт и нажмите кодирование. Для обработки переключите режим и укажите входы и фактические выходы машины.
Молекулярный сборщик с интерфейсом и процессор крафта — две независимые подготовки. Для обычного рецепта положите записанный шаблон в интерфейс, рядом поставьте сборщик и обеспечьте питание и канал интерфейса.
Заказ станет доступен после соединения трёх веток: шаблон + исполнитель + процессор. Контроллер нужен при расширении каналов; небольшая сеть на восьми каналах может работать без него. Продвинутый высекатель и редактор шаблонов не требуют уже выполненного первого заказа.''')
page('ie_coke','Коксовая печь: 27 блоков','''Соберите сплошной куб 3×3×3 из 27 коксовых кирпичей. Примените инженерный молот к центральному блоку одной вертикальной стороны. Если структура не сформировалась, проверьте центр, все 27 блоков и отсутствие подменённых декоративных кирпичей.
Поместите уголь и свободную ёмкость для креозота. Печь не требует RF. Полный внутренний бак останавливает производство: заранее подключите отвод креозота. Древесный уголь и угольный кокс — разные результаты.''')
page('ie_steel','Доменная печь: отдельная структура','''Изготовьте доменные кирпичи и соберите предусмотренный руководством куб 3×3×3. Сформируйте его инженерным молотом по центральной грани. Коксовая печь не превращается в доменную от смены топлива.
Подайте железо и поддерживаемое топливо, например угольный кокс. Забирайте сталь и шлак; переполненный побочный выход тоже останавливает обработку. Продвинутую печь с подогревателями стройте по отдельной записи инженерного руководства.''')
page('bot_plate','Террасталь: слои и маноснабжение','''Нижний слой 3×3: лазуритовые блоки в центре и четырёх углах, живой камень в серединах четырёх сторон. Пластину земной агломерации поставьте на центральный лазурит сверху.
Подведите ману искрами от наполненного бассейна: искра нужна над бассейном и над пластиной. Для первой обычной операции требуется половина полного бассейна маны, но проверяйте рецепт сборки.
Бросьте на пластину один манастальной слиток, один алмаз маны и одну жемчужину маны. Не подбирайте их до завершения. Наладьте достаточный запас маны до подачи предметов; присутствие бассейна рядом само по себе не означает, что он подключён.''')
page('bot_runes','Рунический алтарь: завершение','''Поставьте рунический алтарь, направьте на него распространитель маны и свяжите распространитель с наполненным бассейном. Внесите ингредиенты ровно одного рецепта.
Когда алтарь получит нужную ману и покажет готовность, бросьте живой камень и примените Посох леса. Сначала дождитесь готовности, затем завершайте; добавление нового набора ингредиентов до окончания смешивает действия.
При автоматизации учитывайте руны, которые возвращаются после операции. Возвратная руна не должна навсегда оставаться в буфере, если МЭ ждёт её обратно.''')
page('for_farm','Мультиферма Forestry: проверка слоёв','''Выберите размер из руководства Forestry и соберите корпус из фермерских блоков. Рабочий верхний слой должен включать поддерживаемый редуктор, вентиль и люк вместо соответствующих блоков корпуса.
Подведите воду к вентилю, энергию к редуктору и предметную логистику к люку. Во внутренний запас положите удобрение. Выберите электронную плату с лампами под нужный тип хозяйства.
Снаружи организуйте площадь подходящей почвы в зоне обслуживания. Сначала проверьте посадку и сбор одного вида культуры, затем расширяйте. Пустой запас удобрения, неверная плата и отсутствие воды проверяются отдельно.''')
page('gen_template','Шаблон генома: независимая подготовка','''До первой модификации создайте генетический шаблон. Пробоотборник извлекает отдельные признаки; соответствующие образцы устанавливаются в шаблон. Разные признаки занимают разные позиции, один признак не заменяет полный геном.
Для импринтера приготовьте шаблон, целевую особь и требуемые расходники. Сначала примените один понятный признак и подтвердите его анализатором. Сохраните исходную линию и не расходуйте единственную принцессу.
Промышленная пасека и получение шаблона — параллельные направления. Рабочая пасека не доказывает, что геном уже подготовлен.''')
page('tic_smeltery','Плавильня: минимальная сборка','''Сделайте основание из обожжённых кирпичей 3×3. По его периметру поставьте стену высотой один блок; внутренний объём над основанием 3×3 оставьте пустым. Контроллер и резервуар заменяют блоки стены; слив также находится в стене.
Заполните резервуар лавой. Установите кран на слив, а под ним литейный стол или резервуар. Контроллер должен распознать структуру; если нет, проверьте сплошной пол, замкнутый периметр и отсутствие внутренних блоков.
Для формы положите образец на стол и залейте подходящий материал формы, например алюминиевую латунь. Затем слейте нужный металл. Проверяйте порядок жидкостей в контроллере и пропорции сплавов до загрузки.''')

